"""File storage interface (local directory now, S3-compatible later)."""

from __future__ import annotations

import re
from pathlib import Path
from typing import Protocol

_SAFE_KEY = re.compile(r"^[a-z0-9][a-z0-9/_.-]{0,199}$")


class InvalidKey(ValueError):
    pass


def validate_key(key: str) -> str:
    """Keys are generated by us (uuid-based); still reject anything that could escape the root."""
    if not _SAFE_KEY.match(key) or ".." in key or key.startswith("/") or "//" in key:
        raise InvalidKey(key)
    return key


class Storage(Protocol):
    async def save(self, key: str, data: bytes, content_type: str) -> None: ...

    async def delete(self, key: str) -> None: ...

    def url(self, key: str) -> str: ...


class LocalStorage:
    """Stores files under `root`; served by the API at `url_prefix` with long-lived cache headers."""

    def __init__(self, root: Path, url_prefix: str = "/media", base_url: str = "") -> None:
        self.root = root.resolve()
        self.url_prefix = url_prefix.rstrip("/")
        self.base_url = base_url.rstrip("/")

    def path_for(self, key: str) -> Path:
        validate_key(key)
        path = (self.root / key).resolve()
        if not path.is_relative_to(self.root):
            raise InvalidKey(key)
        return path

    async def save(self, key: str, data: bytes, content_type: str) -> None:
        path = self.path_for(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_bytes(data)
        tmp.replace(path)

    async def delete(self, key: str) -> None:
        self.path_for(key).unlink(missing_ok=True)

    def url(self, key: str) -> str:
        validate_key(key)
        return f"{self.base_url}{self.url_prefix}/{key}"
